Suppose Assumption \ref{assump: lip_convexity} holds. The hypergradient $\nabla\Phi(x)$ of \eqref{eq: dsbo_opt} takes the form:
\begin{equation}\label{eq: hypergrad}
    \begin{aligned}
        \nabla\Phi(x) = &\frac{1}{n}\left(\sum_{i=1}^{n}\nabla_xf_i(\tilde{x})\right) \\
        &- \nabla_{xy}^2g(\tilde{x})\left(\nabla_y^2g(\tilde{x} )\right)^{-1}\left[\frac{1}{n}\left(\sum_{i=1}^{n}\nabla_yf_i(\tilde{x})\right)\right],
    \end{aligned}
\end{equation}
where $\tilde{x} = (x, y^*(x))$.

\caption{Hessian-Inverse-Gradient Product oracle}\label{algo: HIGP_oracle}

\begin{algorithmic}[1]
    \STATE {\bfseries Input:} $(H_{i,t}^{(k)}, b_{i,t}^{(k)})$, for $0\leq t\leq N$ accessible only to agent $i$. Stepsize $\gamma$, iteration number $N$, $d_{i,0}^{(k)} = -b_{i,0}^{(k)},\ s_{i,0}^{(k)} = - b_{i,0}^{(k)},\ \text{and } z_{i,0}^{(k)} = 0$

    \FOR{$t=0,1,...,N-1$}
        \FOR{$i=1,...,n$}
            \STATE $z_{i,t+1}^{(k)} = \sum_{j=1}^{n}w_{ij}z_{j,t}^{(k)} - \gamma d_{i,t}^{(k)}$, \\
            \STATE $s_{i,t+1}^{(k)} = H_{i,t+1}^{(k)}z_{i,t+1}^{(k)}- b_{i,t+1}^{(k)}$, \\
            \STATE $d_{i,t+1}^{(k)} =\sum_{j=1}^{n}w_{ij}d_{j,t}^{(k)} + s_{i,t+1}^{(k)} - s_{i,t}^{(k)}$
        \ENDFOR
    \ENDFOR
    \STATE {\bfseries Output:}{$z_{i,N}^{(k)} $ on each node.}
\end{algorithmic}

    \begin{algorithmic}[1]
        \caption{MA-DSBO Algorithm}\label{algo:DSBO}
    	\STATE {\bfseries Input:} Stepsizes $\alpha_k, \beta_k$, iteration numbers $K, T, N$, $y_{i,k}^{(0)} = 0$, and $x_{i,0} = r_{i,0} = 0$. 
    	\FOR{$k=0,1,...,K-1$}
    	    \STATE $y_{i,k}^{(0)} = y_{i,k-1}^{(T)}$. \\
    		\FOR{$t=0,1,..., T-1$}
    		    \FOR{$i=1,...,n$}
        		    \STATE $y_{i,k}^{(t+1)} = \sum_{j=1}^{n}w_{ij}y_{j,k}^{(t)} -\beta_k v_{i,k}^{(t)}$ \text{ with } $v_{i,k}^{(t)} = \nabla_yg_i(x_{i,k}, y_{i,k}^{(t)}; \tilde{\xi}_{i,k}^{(t)})$
    		    \ENDFOR
            \ENDFOR
            \STATE Run Algorithm \ref{algo: Hypergrad} and set the output as $u_{i,k}$. \\
            \FOR{$i=1,...,n$}
                \STATE $x_{i,k+1} = \sum_{j=1}^{n}w_{ij}x_{j,k} - \alpha_k r_{i,k}$. \\
        		\STATE $r_{i,k+1} = (1-\alpha_k)r_{i,k} + \alpha_ku_{i,k}$.
            \ENDFOR
        \ENDFOR
	\STATE {\bfseries Output:} $\bar{x}_K = \frac{1}{n}\sum_{i=1}^{n}x_{i,K}.$
    \end{algorithmic}

\label{thm: main}
Suppose Assumptions \ref{assump: lip_convexity}, \ref{assump: W}, \ref{assump: similarity_of_g}, and \ref{assump: stoc_derivatives} hold. There exist constants \footnote{The constants are independent of $K$ and the details are given in the appendix.} $0<c_1<c_2$ such that in Algorithm \ref{algo:DSBO} if we set $\gamma\in (c_1, c_2)$, $T\geq 1$, and
    \begin{align*}
        \alpha_k \equiv \Theta\left(\frac{1}{\sqrt{K}}\right),\ \beta_k \equiv \Theta\left(\frac{1}{\sqrt{K}}\right),\ N = \Theta\left(\log K\right), 
    \end{align*}
    then we have
    \[
        \begin{aligned}
            \min_{0\leq k\leq K}\mathbb{E}\left[\|\nabla\Phi(\bar{x}_k)\|^2\right] &= \mathcal{O}\left(\frac{1}{\sqrt{K}}\right), \\
            \min_{0\leq k\leq K}\frac{\mathbb{E}\left[\|X_k - \bar{x}_k\mathbf{1}^{\top}_n\|^2\right]}{n} &= \mathcal{O}\left(\frac{1}{K}\right).
        \end{aligned}
    \]

Define
\begin{align*}
    y_k^* &= y^*(\bar{x}_k), \\
    z_{*}^{(k)} &= \left(\sum_{i=1}^{n}\nabla_y^2g_i(\bar{x}_k,y_k^*)\right)^{-1}\left(\sum_{i=1}^{n}\nabla_y f_i(\bar{x}_k, y_k^*)\right).
\end{align*}

To bound the hypergradient estimation error, a rough analysis (see Lemma \ref{lem: last}) shows that $\mathbb{E}\left[\|\mathbb{E}\left[\bar{u}_k|\mathcal{F}_k\right] - \nabla\Phi(\bar{x}_k)\|^2\right] =$
\[
    \begin{aligned}
        &\resizebox{\hsize}{!}{$\mathcal{O}\Big(\mathbb{E}\left[\|X_k - \bar{x}_k\mathbf{1}^{\top}\|^2 + \|Y_k^{(T)} - \bar{y}_k^{(T)}\mathbf{1}^{\top}\|^2 + \|\bar{y}_k^{(T)} - y_k^*\|^2\right]$} \\ 
        &\resizebox{\hsize}{!}{$+ \mathbb{E}\left[\|\mathbb{E}\left[z_{i,N}^{(k)} - \bar{z}_{N}^{(k)}|\mathcal{F}_k\right]\|^2 + \|\mathbb{E}\left[\bar{z}_N^{(k)}|\mathcal{F}_k\right] - z_*^{(k)}\|^2\right]\Big),$}
    \end{aligned}
\]
where the first two terms on the right hand side denote the consensus error among agents, and can be bounded via techniques in decentralized optimization (Lemma \ref{lem: XY_cons}).

\begin{align*}
