\label{lem: XY_cons}
    Suppose Assumptions \ref{assump: lip_convexity}, \ref{assump: W}, \ref{assump: similarity_of_g}, and \ref{assump: stoc_derivatives} hold. Define
    \begin{align*}
        &\sigma_u^2 = 2(L_{f,0}^2 + \sigma_f^2) + 2(L_{g,1}^2 + \sigma_{g,2}^2)\sigma_z^2,\ \sigma_x^2 = \frac{1+\rho^2}{1-\rho^2}\cdot \sigma_u^2,\ \tilde{\alpha}_{k+1}^2 = \sum_{i=0}^{k}\alpha_i^2\left(\frac{1+\rho^2}{2}\right)^{k-i}, \\
        &\tilde{\beta}_{k+1}^2 = \frac{1+\rho^2}{1-\rho^2}\sum_{i=0}^{k}\beta_i^2(2\sigma_{g,1}^2 + 6L_{g,1}^2\sigma_x^2\tilde{\alpha}_i^2 + 3\delta^2)\left(\frac{3+\rho^2}{4}\right)^{k-i},\ \tilde{\alpha}_0 = \tilde{\beta}_0 = 0.
    \end{align*}
    If $\beta_k$ satisfy
    \begin{equation}\label{ineq: beta_condition}
        \frac{(1+\rho^2)}{2} + \beta_k^2\frac{1+\rho^2}{1-\rho^2}\cdot 6L_{g,1}^2 \leq \frac{3+\rho^2}{4}<1,
    \end{equation}
    then in Algorithm \ref{algo:DSBO}, for any $k\geq 0$ and $0\leq t\leq T-1$ we have
    \begin{equation}\label{ineq: XY_consensus}
        \begin{aligned}
            &\mathbb{E}\left[\|U_k\|^2\right]\leq n\sigma_u^2,\ \mathbb{E}\left[\|X_k - \bar{x}_k\mathbf{1}^{\top}\|^2\right]\leq n\sigma_x^2\tilde{\alpha}_k^2, \\ 
            &\frac{1}{n}\mathbb{E}\left[\|Y_{k}^{(t)} - \bar{y}_{k}^{(t)}\mathbf{1}^{\top}\|^2\right]\leq \left[\left(\frac{3+\rho^2}{4}\right)^{t}T - t\left(\frac{3+\rho^2}{4}\right)\right]\tilde{\beta}_k^2 + t\tilde{\beta}_{k+1}^2.
        \end{aligned}
    \end{equation}

Note that the inner and outer loop updates satisfy
\begin{align*}
    &\bar{x}_{k+1} = \bar{x}_k - \alpha_k \bar{r}_k,\ X_{k+1} - \bar{x}_{k+1}\mathbf{1}^{\top} = X_kW - \bar{x}_k\mathbf{1}^{\top} - \alpha_k(R_k - \bar{r}_k\mathbf{1}^{\top}), \\
    &\bar{y}_k^{(t+1)} = \bar{y}_k^{(t)} - \beta_k\bar{v}_k^{(t)},\ Y_{k}^{(t+1)} - \bar{y}_k^{(t+1)} = Y_k^{(t)}W - \bar{y}_k^{(t)}\mathbf{1}^{\top} - \beta_k(V_k^{(t)} - \bar{v}_k^{(t)}\mathbf{1}^{\top}),
\end{align*}
which gives
\begin{align}
    &\|X_{k+1} - \bar{x}_{k+1}\mathbf{1}^{\top}\|^2 \leq \frac{(1+\rho^2)}{2}\|X_k - \bar{x}_k\mathbf{1}^{\top}\|^2 + \alpha_k^2\frac{1+\rho^2}{1-\rho^2}\|R_k - \bar{r}_k\mathbf{1}^{\top}\|^2, \label{ineq: X_cons_recursion}\\
    &\|Y_{k}^{(t+1)} - \bar{y}_{k}^{(t+1)}\mathbf{1}^{\top}\|^2 \leq \frac{(1+\rho^2)}{2}\|Y_k^{(t)} - \bar{y}_k^{(t)}\mathbf{1}^{\top}\|^2 + \beta_k^2\frac{1+\rho^2}{1-\rho^2}\|V_k^{(t)} - \bar{v}_k^{(t)}\mathbf{1}^{\top}\|^2. \label{ineq: Y_cons_recursion}
\end{align}
The inequalities hold similarly as the inequality in \eqref{ineq: consensus_ineq}. Notice that we have
\begin{align*}
    &\|R_k - \bar{r}_k\mathbf{1}^{\top}\| = \|R_k\left(I - \frac{\mathbf{1}\mathbf{1}^{\top}}{n}\right)\| = \|\left[(1-\alpha_k)R_{k-1} + \alpha_kU_{k-1}\right]\left(I-\frac{\mathbf{1}\mathbf{1}^{\top}}{n}\right)\|\\
    \leq &\max\left(\|R_{k-1}\left(I-\frac{\mathbf{1}\mathbf{1}^{\top}}{n}\right)\|,\ \|U_{k-1}\left(I-\frac{\mathbf{1}\mathbf{1}^{\top}}{n}\right)\|\right)\leq \max_{0\leq i\leq k-1}\left(\|U_{i}\left(I-\frac{\mathbf{1}\mathbf{1}^{\top}}{n}\right)\|\right).
\end{align*}
The second inequality holds by repeating the first inequality multiple times. For each $\|U_k - \bar{u}_k\mathbf{1}^{\top}\|$ we have
\begin{align*}
    &\mathbb{E}\left[\|U_k - \bar{u}_k\mathbf{1}^{\top}\|^2\right] = \mathbb{E}\left[\|U_k\left(I - \frac{\mathbf{1}\mathbf{1}^{\top}}{n}\right)\|^2\right]\leq \mathbb{E}\left[\|U_k\|^2\right] = \sum_{i=1}^{n}\mathbb{E}\left[\|u_{i,k}\|^2\right] \\
    \leq &2\sum_{i=1}^{n}\left(\mathbb{E}\left[\|\nabla_xf_i(x_{i,k}, y_{i,k}^{(T)};\phi_{i,0})\|^2\right] + \mathbb{E}\left[\|\nabla_{xy}^2 g_i(x_{i,k},y_{i,k}^{(T)};\xi_{i,0} )z_{i,N}^{(k)}\|^2\right]\right)\\
    \leq &2\sum_{i=1}^{n}\left(L_{f,0}^2 + \sigma_f^2 + (L_{g,1}^2 + \sigma_{g,2}^2)\mathbb{E}\left[\|z_{i,N}^{(k)}\|^2\right]\right) \leq 2n(L_{f,0}^2 + \sigma_f^2) + 2n(L_{g,1}^2 + \sigma_{g,2}^2)\sigma_z^2 = n\sigma_u^2.
\end{align*}
The fourth inequality uses \eqref{ineq: z_bdd_2_m}. Using the above two inequaities in \eqref{ineq: X_cons_recursion} we know
\[
    \|X_{k+1} - \bar{x}_{k+1}\mathbf{1}^{\top}\|^2 \leq \frac{(1+\rho^2)}{2}\|X_k - \bar{x}_k\mathbf{1}^{\top}\|^2 + n\alpha_k^2\sigma_x^2.
\]
Using Lemma \ref{lem: useful_ineq} and $X_0 = 0$, we can obtain the first two results of \eqref{ineq: XY_consensus}. To analyze $\|V_k^{(t)} - \bar{v}_k^{(t)}\mathbf{1}^{\top}\|$, we first notice that 
\begin{align*}
    v_{i,k}^{(t)} - \bar{v}_k^{(t)} &= v_{i,k}^{(t)} - \nabla_y g_i(x_{i,k}, y_{i,k}^{(t)}) - (\bar{v}_k^{(t)} - \frac{1}{n}\sum_{l=1}^{n}\nabla_yg_l(x_{l,k}, y_{l,k}^{(t)})) + \nabla_y g_i(x_{i,k}, y_{i,k}^{(t)}) - \nabla_yg_i(\bar{x}_k, \bar{y}_k^{(t)}) \\
    &- \frac{1}{n}\sum_{l=1}^{n}(\nabla_yg_l(x_{l,k}, y_{l,k}^{(t)}) - \nabla_yg_l(\bar{x}_k, \bar{y}_k^{(t)}))
    +\nabla_yg_i(\bar{x}_k, \bar{y}_k^{(t)}) - \frac{1}{n}\sum_{l=1}^{n}\nabla_yg_l(\bar{x}_k, \bar{y}_k^{(t)}).
\end{align*}
Hence we know 
\begin{align*}
    &\mathbb{E}\left[\|V_k^{(t)} - \bar{v}_k^{(t)}\mathbf{1}^{\top}\|^2\right] = \sum_{i=1}^{n}\mathbb{E}\left[\|v_{i,k}^{(t)} - \bar{v}_k^{(t)}\|^2\right] \\
    \leq & (n+1)\sigma_{g,1}^2 + 3\sum_{i=1}^{n}\mathbb{E}\left[L_{g,1}^2(\|x_{i,k} - \bar{x}_k\|^2 + \|y_{i,k}^{(t)} - \bar{y}_k^{(t)}\|^2) + \frac{L_{g,1}^2}{n}\sum_{l=1}^{n}(\|x_{l,k} - \bar{x}_k\|^2 + \|y_{l,k}^{(t)}-\bar{y}_k^{(t)}\|^2) + \delta^2\right]\\
    = &(n+1)\sigma_{g,1}^2 + 6L_{g,1}^2\mathbb{E}\left[\|X_k - \bar{x}_k\mathbf{1}^{\top}\|^2 + \|Y_{k} - \bar{y}_k^{(t)}\mathbf{1}^{\top}\|^2\right] + 3n\delta^2 \\
    \leq &6L_{g,1}^2\mathbb{E}\left[\|Y_k^{(t)} - \bar{y}_k^{(t)}\mathbf{1}^{\top}\|^2\right] + 2n\sigma_{g,1}^2 + 6nL_{g,1}^2\sigma_x^2\tilde{\alpha}_k^2 + 3n\delta^2,
\end{align*}
where the second inequality uses the first result of \eqref{ineq: XY_consensus}. The above inequality together with \eqref{ineq: Y_cons_recursion} imply
\begin{equation}\label{ineq: Y_kt_cons_recursion}
    \begin{aligned}
        &\frac{1}{n}\mathbb{E}\left[\|Y_{k}^{(t+1)} - \bar{y}_{k}^{(t+1)}\mathbf{1}^{\top}\|^2\right] \\
    \leq &\left[\frac{(1+\rho^2)}{2} + \beta_k^2\frac{1+\rho^2}{1-\rho^2}\cdot 6L_{g,1}^2 \right]\cdot\frac{1}{n}\mathbb{E}\left[\|Y_k^{(t)} - \bar{y}_k^{(t)}\mathbf{1}^{\top}\|^2\right] + \beta_k^2\frac{1+\rho^2}{1-\rho^2}(2\sigma_{g,1}^2 + 6L_{g,1}^2\sigma_x^2\tilde{\alpha}_k^2 + 3\delta^2) \\
    \leq &\left(\frac{3+\rho^2}{4}\right)^{t+1}\cdot\frac{1}{n}\mathbb{E}\left[\|Y_k^{(0)} - \bar{y}_k^{(0)}\mathbf{1}^{\top}\|^2\right] + \beta_k^2\frac{1+\rho^2}{1-\rho^2}(2\sigma_{g,1}^2 + 6L_{g,1}^2\sigma_x^2\tilde{\alpha}_k^2 + 3\delta^2)\sum_{l=0}^{t}\left(\frac{3+\rho^2}{4}\right)^i \\
    \leq &\left(\frac{3+\rho^2}{4}\right)^{t+1}\cdot\frac{1}{n}\mathbb{E}\left[\|Y_k^{(0)} - \bar{y}_k^{(0)}\mathbf{1}^{\top}\|^2\right] + (t+1)\beta_k^2\frac{1+\rho^2}{1-\rho^2}(2\sigma_{g,1}^2 + 6L_{g,1}^2\sigma_x^2\tilde{\alpha}_k^2 + 3\delta^2),
    \end{aligned}
\end{equation}
where the second inequality uses Lemma \ref{lem: useful_ineq} and \eqref{ineq: beta_condition}. Notice that we use warm-start strategy (i.e., $Y_{k+1}^{(0)} = Y_{k}^{(T)}$), hence we know
\begin{align*}
    &\frac{1}{n}\mathbb{E}\left[\|Y_{k+1}^{(0)} - \bar{y}_{k+1}^{(0)}\mathbf{1}^{\top}\|^2\right] = \frac{1}{n}\mathbb{E}\left[\|Y_{k}^{(T)} - \bar{y}_{k}^{(T)}\mathbf{1}^{\top}\|^2\right]\\
        \leq &\left(\frac{3+\rho^2}{4}\right)^{T}\cdot\frac{1}{n}\mathbb{E}\left[\|Y_k^{(0)} - \bar{y}_k^{(0)}\mathbf{1}^{\top}\|^2\right] + T\beta_k^2\frac{1+\rho^2}{1-\rho^2}(2\sigma_{g,1}^2 + 6L_{g,1}^2\sigma_x^2\tilde{\alpha}_k^2 + 3\delta^2) \\
        \leq & T\frac{1+\rho^2}{1-\rho^2}\sum_{i=0}^{k}\beta_i^2(2\sigma_{g,1}^2 + 6L_{g,1}^2\sigma_x^2\tilde{\alpha}_i^2 + 3\delta^2)\left(\frac{3+\rho^2}{4}\right)^{k-i} = T\tilde{\beta}_{k+1}^2,
\end{align*}
where the second inequality uses Lemma \ref{lem: useful_ineq}. Using the above estimation in \eqref{ineq: Y_kt_cons_recursion}, we know
