    \end{equation}
    where $y_k^* = y^*(\bar{x}_k) = arg\,min_y \sum_{i=1}^{n}g_i(\bar{x}_k, y)$

For any $k\geq 0,\ 1\leq t\leq T-1$, define $$\mathcal{G}_t^{(k)} = \sigma\left(\bigcup_{i=1}^{n}\{y_{i,0}^{(T)}, ..., y_{i,k-1}^{(T)}, y_{i,k}^{(t)}, x_{i,0},...,x_{i,k}, r_{i,0},...,r_{i,k}\}\right).$$ 
We know
\begin{align}\label{ineq: inner_1_step}
    \begin{aligned}
        &\mathbb{E}\left[\|\bar{y}_{k}^{(t+1)} - y_k^*\|^2|\mathcal{G}_t\right] \\
    = &\mathbb{E}\left[\|\bar{y}_k^{(t)} - \beta_k\nabla_yg(\bar{x}_k, \bar{y}_k^{(t)}) - y_k^* - \beta_k\left(\bar{v}_k^{(t)} - \mathbb{E}\left[\bar{v}_k^{(t)}|\mathcal{G}_t\right]\right) - \beta_k\left(\mathbb{E}\left[\bar{v}_k^{(t)}|\mathcal{G}_t\right] - \nabla_yg(\bar{x}_k, \bar{y}_k^{(t)})\right)\|^2|\mathcal{G}_t\right] \\
    = & \mathbb{E}\left[\|\bar{y}_k^{(t)} - \beta_k\nabla_yg(\bar{x}_k, \bar{y}_k^{(t)}) - y_k^* - \beta_k\left(\mathbb{E}\left[\bar{v}_k^{(t)}|\mathcal{G}_t\right] - \nabla_yg(\bar{x}_k, \bar{y}_k^{(t)})\right)\|^2|\mathcal{G}_t\right] + \frac{\beta_k^2\sigma_{g,1}^2}{n}\\
    \leq &(1+\beta_k\mu_g)\|\bar{y}_k^{(t)} - \beta_k\nabla_yg(\bar{x}_k, \bar{y}_k^{(t)}) - y_k^*\|^2 + \left(1+\frac{1}{\beta_k\mu_g}\right)\beta_k^2\mathbb{E}\left[\|\mathbb{E}\left[\bar{v}_k^{(t)}|\mathcal{G}_t\right] - \nabla_yg(\bar{x}_k, \bar{y}_k^{(t)})\|^2|\mathcal{G}_t\right] +\frac{\beta_k^2\sigma_{g,1}^2}{n}\\
    \leq & (1+\beta_k\mu_g)(1 - \beta_k\mu_g)^2\|\bar{y}_k^{(t)}-y_k^*\|^2 + \left(\frac{\beta_k}{\mu_g} + \beta_k^2\right)\|\frac{1}{n}\sum_{i=1}^{n}\left(\nabla_yg_i(x_{i,k},y_{i,k}^{(t)}) - \nabla_yg_i(\bar{x}_k,\bar{y}_k^{(t)})\right)\|^2 + \frac{\beta_k^2\sigma_{g,1}^2}{n} \\
    \leq & (1 - \beta_k\mu_g)\|\bar{y}_k^{(t)}-y_k^*\|^2 + \frac{\left(\frac{\beta_k}{\mu_g} + \beta_k^2\right)L_{g,1}^2}{n}\left(\|X_k - \bar{x}_k\mathbf{1}^{\top}\|^2 + \|Y_k^{(t)} - \bar{y}_k^{(t)}\mathbf{1}^{\top}\|^2\right) + \frac{\beta_k^2\sigma_{g,1}^2}{n},
