\begin{align*}
    &\Phi(\bar{x}_{k+1}) - \Phi(\bar{x}_k) + \frac{1}{2}\mathbb{E}\left[\|\bar{r}_{k+1}\|^2|\mathcal{F}_k\right] - \frac{1}{2}\|\bar{r}_k\|^2\\
    \leq &\alpha_k(\mathbb{E}\left[\bar{u}_k|\mathcal{F}_k\right] - \nabla\Phi(\bar{x}_k))^{\top}\bar{r}_k + (\frac{L_{\Phi}\alpha_k^2}{2} - \alpha_k)\|\bar{r}_k\|^2 + \frac{1}{2}\mathbb{E}\left[\|\bar{r}_{k+1} - \bar{r}_k\|^2|\mathcal{F}_k\right] \\
    \leq & \frac{\alpha_k}{2}\left(\|\mathbb{E}\left[\bar{u}_k|\mathcal{F}_k\right] - \nabla\Phi(\bar{x}_k)\|^2 + \|\bar{r}_k\|^2\right) + (\frac{L_{\Phi}\alpha_k^2}{2} - \alpha_k)\|\bar{r}_k\|^2 + \frac{1}{2}\mathbb{E}\left[\|\bar{r}_{k+1} - \bar{r}_k\|^2|\mathcal{F}_k\right],
\end{align*}
which implies
\begin{equation}\label{ineq: sum_r_original}
    \begin{aligned}
        &\left(\frac{\alpha_k}{2} - \frac{L_{\Phi}\alpha_k^2}{2}\right)\mathbb{E}\left[\|\bar{r}_k\|^2\right]\\
    \leq &\frac{\alpha_k}{2}\mathbb{E}\left[\|\mathbb{E}\left[\bar{u}_k|\mathcal{F}_k\right] - \nabla\Phi(\bar{x}_k)\|^2\right] +   \frac{1}{2}\mathbb{E}\left[\|\bar{r}_{k+1} - \bar{r}_k\|^2\right] + \mathbb{E}\left[\Phi(\bar{x}_k) - \Phi(\bar{x}_{k+1})\right] +\frac{1}{2}\mathbb{E}\left[\|\bar{r}_k\|^2\right] - \frac{1}{2}\mathbb{E}\left[\|\bar{r}_{k+1}\|^2\right]\\
    \leq &\frac{\alpha_k}{2}\mathbb{E}\left[\|\mathbb{E}\left[\bar{u}_k|\mathcal{F}_k\right] - \nabla\Phi(\bar{x}_k)\|^2\right] + 2\alpha_k^2\sigma_u^2 + \mathbb{E}\left[\Phi(\bar{x}_k) - \Phi(\bar{x}_{k+1})\right] +\frac{1}{2}\mathbb{E}\left[\|\bar{r}_k\|^2\right] - \frac{1}{2}\mathbb{E}\left[\|\bar{r}_{k+1}\|^2\right],
    \end{aligned}
\end{equation}
where the second inequality holds since we know
\begin{align*}
    &\mathbb{E}\left[\|\bar{r}_k\|^2\right]\leq \max\left(\mathbb{E}\left[\|\bar{r}_{k-1}\|^2\right], \mathbb{E}\left[\|\bar{u}_k\|^2\right]\right)\leq \max_{0\leq i\leq k}\mathbb{E}\left[\|\bar{u}_i\|^2\right]\leq \sigma_u^2, \\
    &\mathbb{E}\left[\|\bar{r}_{k+1} - \bar{r}_k\|^2\right] = \alpha_k^2\mathbb{E}\left[\|\bar{r}_k - \bar{u}_k\|^2\right]\leq 2\alpha_k^2\mathbb{E}\left[\|\bar{r}_k\|^2 + \|\bar{u}_k\|^2\right]\leq 4\sigma_u^2.
\end{align*}
In these two conclusions $\mathbb{E}\left[\|\bar{u}_i\|^2\right]\leq \sigma_u^2$ is due to the first inequality in \eqref{ineq: XY_consensus}. Taking summation on both sides of \eqref{ineq: sum_r_original}, we have~\eqref{ineq: main_of_MA}.

\label{lem: last}
    In Algorithm \ref{algo:DSBO} if we define
