        \sum_{k=0}^{K}\alpha_k\|\mathbb{E}\left[\bar{u}_k|\mathcal{F}_k\right] - \nabla\Phi(\bar{x}_k)\|^2 &= C_y\sum_{k=0}^{K}\alpha_k\|\bar{y}_k^{(T)} - y_k^*\|^2 + \mathcal{O}\left(1 + \left(1-\frac{\gamma\mu_g}{2}\right)^{N}\sum_{k=0}^{K}\alpha_k\right), \\ 
        \frac{1}{K}\sum_{k=0}^{K}\mathbb{E}\left[\|\nabla\Phi(\bar{x}_k)\|^2\right] &= \mathcal{O}\left(\frac{1}{\sqrt{K}}\right).
