\begin{align*}
        &\alpha_k = \frac{\mu_g^4}{3L_{g,1}^2C_y}\cdot\beta_k \equiv \frac{1}{\sqrt{K}},\ \gamma \text{ such that \eqref{ineq: gamma_for_quadratics} holds},\  N = \Theta(\log K),\ T\geq 1, \\
        &C_y = 5\left(L_{f,1}^2 + \frac{L_{g,2}^2L_{f,0}^2}{\mu_g^2}\right) + 50L_{g,1}^2\left(\frac{1}{\mu_g^2} + \frac{\gamma}{\mu_g}\right)\left(L_{g,2}^2\sigma_z^2 + L_{f,1}^2\right).
    \end{align*}

Notice that we have
\begin{align*}
    \mathbb{E}\left[\bar{u}_{k}|\mathcal{F}_k\right] &= \frac{1}{n}\sum_{i=1}^{n}\nabla_x f_i(x_{i,k},y_{i,k}^{(T)}) - \frac{1}{n}\sum_{i=1}^{n}\nabla_{xy}^2 g_i(x_{i,k},y_{i,k}^{(T)})\mathbb{E}\left[z_{i,N}^{(k)}|\mathcal{F}_k\right], \\
    \nabla\Phi(\bar{x}_k) &= \frac{1}{n}\sum_{i=1}^{n}\nabla_x f_i(\bar{x}_k, y_k^*) - \left(\frac{1}{n}\sum_{i=1}^{n}\nabla_{xy}^2 g_i(\bar{x}_k, y_k^*)\right)\left(\frac{1}{n}\sum_{i=1}^{n}\nabla_y^2g_i(\bar{x}_k, y_k^*)\right)^{-1}\left(\frac{1}{n}\sum_{i=1}^{n}\nabla_y f_i(\bar{x}_k, y_k^*)\right), \\
    &=\frac{1}{n}\sum_{i=1}^{n}\nabla_x f_i(\bar{x}_k, y_k^*) - \frac{1}{n}\left(\sum_{i=1}^{n}\nabla_{xy}^2 g_i(\bar{x}_k, y_k^*)\right)\left(\sum_{i=1}^{n}\nabla_y^2g_i(\bar{x}_k, y_k^*)\right)^{-1}\left(\sum_{i=1}^{n}\nabla_y f_i(\bar{x}_k, y_k^*)\right) \\
    &= \frac{1}{n}\sum_{i=1}^{n}\nabla_x f_i(\bar{x}_k, y_k^*) - \frac{1}{n}\left(\sum_{i=1}^{n}\nabla_{xy}^2 g_i(\bar{x}_k, y_k^*)\right)z_*^{(k)}.
\end{align*}
Hence we know
\begin{align*}
    &\|\mathbb{E}\left[\bar{u}_k|\mathcal{F}_k\right] - \nabla\Phi(\bar{x}_k)\| \\
    = &\frac{1}{n}\sum_{i=1}^{n}\left(\|\nabla_x f_i(x_{i,k},y_{i,k}^{(T)}) - \nabla_xf_i(\bar{x}_k,\bar{y}_k^{(T)})\| + \|\nabla_xf_i(\bar{x}_k,\bar{y}_k^{(T)}) - \nabla_x f_i(\bar{x}_k, y_k^*)\|\right) \\
    + & \frac{1}{n}\sum_{i=1}^{n}\left(\|\nabla_{xy}^2g_i(x_{i,k},y_{i,k}^{(T)})\left(\mathbb{E}\left[z_{i,N}^{(k)}|\mathcal{F}_k\right] - z_*^{(k)}\right)\| + \|\left(\nabla_{xy}^2g_i(x_{i,k},y_{i,k}^{(T)}) - \nabla_{xy}^2 g_i(\bar{x}_k, \bar{y}_k^{(T)})\right)z_*^{(k)}\|\right) \\
    + & \frac{1}{n}\sum_{i=1}^{n}\|\left(\nabla_{xy}^2 g_i(\bar{x}_k, \bar{y}_k^{(T)}) - \nabla_{xy}^2 g_i(\bar{x}_k, y_k^*)\right)z_*^{(k)}\|,
\end{align*}
which implies
\begin{align*}
    &\|\mathbb{E}\left[\bar{u}_k|\mathcal{F}_k\right] - \nabla\Phi(\bar{x}_k)\|^2 \\
    \leq &\frac{5}{n}\sum_{i=1}^{n}\left[L_{f,1}^2\left(\|x_{i,k}-\bar{x}_k\|^2+ \|y_{i,k}^{(T)} - \bar{y}_k^{(T)}\|^2 + \|\bar{y}_k^{(T)} - y_k^*\|^2\right) + L_{g,1}^2\|\mathbb{E}\left[z_{i,N}^{(k)}|\mathcal{F}_k\right] - z_*^{(k)}\|^2\right] \\
    + &\frac{5}{n}\sum_{i=1}^{n}\left[\frac{L_{g,2}^2L_{f,0}^2}{\mu_g^2}\left(\|x_{i,k}-\bar{x}_k\|^2 + \|y_{i,k}^{(T)} - \bar{y}_k^{(T)}\|^2 + \|\bar{y}_k^{(T)} - y_k^*\|^2\right)\right] \\
    \leq & 5\left(L_{f,1}^2 + \frac{L_{g,2}^2L_{f,0}^2}{\mu_g^2}\right)\cdot \frac{1}{n}\left(\|X_k - \bar{x}_k\mathbf{1}^{\top}\|^2 + \|Y_k^{(T)} - \bar{y}_k^{(T)}\mathbf{1}^{\top}\|^2 + n\|\bar{y}_k^{(T)} - y_k^*\|^2\right) \\
    + &10L_{g,1}^2\cdot\frac{1}{n}\left(\|\mathbb{E}\left[Z_N^{(k)} - \bar{z}_N^{(k)}\mathbf{1}^{\top}|\mathcal{F}_k\right]\|^2\right) + 10L_{g,1}^2\|\mathbb{E}\left[\bar{z}_N^{(k)}|\mathcal{F}_k\right] - z_*^{(k)}\|^2 \\
    \leq & \left[5\left(L_{f,1}^2 + \frac{L_{g,2}^2L_{f,0}^2}{\mu_g^2}\right) + 50L_{g,1}^2\left(\frac{1}{\mu_g^2} + \frac{\gamma}{\mu_g}\right)\left(L_{g,2}^2\sigma_z^2 + L_{f,1}^2\right)\right]\cdot \left(\|\bar{y}_k^{(T)} - y_k^*\|^2 + \sigma_x^2\tilde{\alpha}_k^2 + T\tilde{\beta}_{k+1}^2\right) \\
    + & 30L_{g,1}^2\left(1-\frac{\gamma\mu_g}{2}\right)^N\left(\frac{L_{f,0}^2}{\mu_g^2} + L_{f,0}^2\right) \\
    +& 10L_{g,1}^2\left[(1-\gamma\mu_g)^{N}\cdot\frac{L_{f,0}^2}{\mu_g^2} + 90C_{\tilde{M}}L_{g,1}^2\left(\frac{1}{\mu_g^2} + \frac{\gamma}{\mu_g}\right)\left(\frac{L_{f,0}^2}{\mu_g^2} +L_{f,0}^2\right)\left(1-\frac{2\gamma\mu_g}{3}\right)^{N-1}\right],
\end{align*}
where the third inequality uses \eqref{ineq: XY_consensus}, \eqref{ineq: z_exp_cons} and \eqref{ineq: z_conv_higp}. Taking summation on both sides, we have
\begin{equation}
    \begin{aligned}
        \sum_{k=0}^{K}\alpha_k\|\mathbb{E}\left[\bar{u}_k|\mathcal{F}_k\right] - \nabla\Phi(\bar{x}_k)\|^2 = C_y\sum_{k=0}^{K}\alpha_k\|\bar{y}_k^{(T)} - y_k^*\|^2 + \mathcal{O}\left(\sum_{k=0}^{K}\alpha_k(\tilde{\alpha}_k^2 + \tilde{\beta}_k^2) + \left(1-\frac{\gamma\mu_g}{2}\right)^{N-1}\sum_{k=0}^{K}\alpha_k\right).
    \end{aligned}
\end{equation}
Setting for all $k$ that
\[
    \alpha_k = C_{\alpha,\beta}\cdot\beta_k \equiv \frac{1}{\sqrt{K}},\ C_{\alpha,\beta} = \frac{\mu_g}{2\sqrt{3C_y}L_{y^*}},
\]
and using \eqref{ineq: bar_y_sum} and Lemma \ref{lem: all_const_sum}, we know
\begin{equation}\label{ineq: r_and_grad_final}
    \begin{aligned}
        &\frac{1}{\sqrt{K}}\sum_{k=0}^{K}\mathbb{E}\left[\|\mathbb{E}\left[\bar{u}_k|\mathcal{F}_k\right] - \nabla\Phi(\bar{x}_k)\|^2\right]=C_yC_{\alpha,\beta}\sum_{k=0}^{K}\beta_k\|\bar{y}_k^{(T)} - y_k^*\|^2 + \mathcal{O}\left(\frac{1}{\sqrt{K}} + \sqrt{K}\left(1-\frac{\gamma\mu_g}{2}\right)^{N-1}\right)\\
        = &C_yC_{\alpha,\beta}L_{y^*}^2\sum_{k=0}^{K}\left(\frac{4C_{\alpha,\beta}}{\sqrt{K}\mu_g^2}+\frac{2}{K\mu_g}\right)\mathbb{E}\left[\|\bar{r}_k\|^2\right] + \mathcal{O}\left(1 + \sqrt{K}\left(1-\frac{\gamma\mu_g}{2}\right)^{N-1}\right)\\ 
        =&\sum_{k=1}^{K}\left(\frac{1}{3\sqrt{K}}+\frac{2C_yC_{\alpha,\beta}L_{y^*}^2}{K\mu_g}\right)\mathbb{E}\left[\|\bar{r}_k\|^2\right] + \mathcal{O}\left(1 + \sqrt{K}\left(1-\frac{\gamma\mu_g}{2}\right)^{N-1}\right),
    \end{aligned}
\end{equation}
which together with \eqref{ineq: main_of_MA} and \eqref{eq: smoothness_const} imply 
\begin{align*}
    &\left(\frac{1}{2\sqrt{K}} - \frac{L_{\Phi}}{2K}\right)\sum_{k=0}^{K}\mathbb{E}\left[\|\bar{r}_k\|^2\right] \\
    \leq &\frac{1}{2\sqrt{K}}\sum_{k=0}^{K}\mathbb{E}\left[\|\mathbb{E}\left[\bar{u}_k|\mathcal{F}_k\right] - \nabla\Phi(\bar{x}_k)\|^2\right] + 2\sigma_u^2\sum_{k=0}^{K}\frac{1}{K} + \Phi(0) - \inf_x\Phi(x) + \frac{1}{2}\mathbb{E}\left[\|\bar{r}_0\|^2\right] \\
    \leq &\frac{1}{2\sqrt{K}}\sum_{k=1}^{K}\left(\frac{1}{3}+\frac{2C_yC_{\alpha,\beta}L_{y^*}^2}{\sqrt{K}\mu_g}\right)\mathbb{E}\left[\|\bar{r}_k\|^2\right] + \mathcal{O}\left(1 + \sqrt{K}\left(1-\frac{\gamma\mu_g}{2}\right)^{N-1}\right).
\end{align*}
Hence we know
\begin{align*}
    \left(\frac{1}{3\sqrt{K}} - \frac{L_{\Phi}}{2K} - \frac{C_yC_{\alpha,\beta}L_{y^*}^2}{K\mu_g}\right)\sum_{k=0}^{K}\mathbb{E}\left[\|\bar{r}_k\|^2\right] = \mathcal{O}\left(1 + \sqrt{K}\left(1-\frac{\gamma\mu_g}{2}\right)^{N-1}\right).
\end{align*}
Using the above expression, \eqref{ineq: r_and_grad_final} and Lemma \ref{lem: r_and_grad}, we know 
\begin{align*}
    \frac{1}{\sqrt{K}}\sum_{k=0}^{K}\mathbb{E}\left[\|\nabla\Phi(\bar{x}_k)\|^2\right]\leq \frac{2}{\sqrt{K}}\sum_{k=0}^{K}\mathbb{E}\left[\|\bar{r}_k\|^2 + \|\bar{r}_k - \nabla\Phi(\bar{x}_k)\|^2\right] = \mathcal{O}\left(1 + \sqrt{K}\left(1-\frac{\gamma\mu_g}{2}\right)^{N-1}\right),
\end{align*}
for sufficiently large $K$. Note that $\gamma$ is in a constant interval by \eqref{ineq: gamma_for_quadratics}, hence $\left(1-\frac{\gamma\mu_g}{2}\right)$ is a constant that is independent of $K$. Picking $N = \Theta(\log K)$ such that $\left(1-\frac{\gamma\mu_g}{2}\right)^{N-1} = \mathcal{O}\left(\frac{1}{\sqrt{K}}\right)$, we know
\[
    \frac{1}{K}\sum_{k=0}^{K}\mathbb{E}\left[\|\nabla\Phi(\bar{x}_k)\|^2\right] = \mathcal{O}\left(\frac{1}{\sqrt{K}}\right).
\]
Moreover, from \eqref{ineq: XY_consensus} we know:
\[
    \frac{1}{K}\sum_{k=0}^{K}\frac{\mathbb{E}\left[\|X_k - \bar{x}_k\mathbf{1}^{\top}\|^2\right]}{n} = \mathcal{O}\left(\frac{1}{K}\sum_{k=0}^{K}\tilde{\alpha}_k^2\right) = \mathcal{O}\left(\frac{1}{K}\right),
\]
where the second equality holds due to Lemma \ref{lem: all_const_sum}
The above two equalities prove Theorem \ref{thm: main}. To find an $\epsilon$-stationary point, we may set $K = \Theta(\epsilon^{-2})$ and we know from $T\geq 1,\ N=\log K$ that the sample complexity will be
$\tilde{\mathcal{O}}(\epsilon^{-2})$.

